   51	    public function plan(int $playerId): ?QueueableTransfer
   52	    {
   53	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   54	        if ($profile === null) {
   55	            return null;
   56	        }
   57	
   58	        if (!User::query()->whereKey($playerId)->exists()) {
   59	            return null;
   60	        }
   61	
   62	        $player = $this->playerServiceFactory->make($playerId, true);
   63	        $planets = $player->planets->all();
   64	        if (count($planets) < 2) {
   65	            return null;
   66	        }
   67	
   68	        foreach ($planets as $planet) {
   69	            $planet->updateResources(false);
   70	            $planet->updateResourceProductionStats(false);
   71	            $planet->updateResourceStorageStats(false);
   72	        }
   73	
   74	        foreach ($planets as $target) {
   75	            $need = $this->need($target, $profile, $playerId);
   76	            if ($need === null || !$this->worthShipping($need)) {
   77	                continue;
   78	            }
   79	
   80	            $source = $this->source($planets, $target, $need, $player);
   81	            if ($source === null) {
   82	                continue;
   83	            }
   84	
   85	            return app()->makeWith(QueueableTransfer::class, [
   86	                'sourcePlanetId' => $source->getPlanetId(),
   87	                'targetPlanetId' => $target->getPlanetId(),
   88	                'metal' => (int) round($need->metal->get()),
   89	                'crystal' => (int) round($need->crystal->get()),
   90	                'deuterium' => (int) round($need->deuterium->get()),
   91	            ]);
   92	        }
   93	
   94	        return $this->surplus($planets, $player);
   95	    }
   96	
   97	    /**
   98	     * The reverse of the need-driven ferry: a planet about to overflow ships its
   99	     * above-floor surplus to the best-developed body, so the mines do not stall
  100	     * (E9/X2). A moon keeps its deuterium for fleet jumps; a planet sweeps all
  101	     * three resources.
  102	     *
  103	     * @param array<PlanetService> $planets
  104	     */
  105	    private function surplus(array $planets, PlayerService $player): ?QueueableTransfer
  106	    {
  107	        $drop = $this->dropBody($planets);
  108	        if ($drop === null) {
  109	            return null;
  110	        }
  111	
  112	        foreach ($planets as $source) {
  113	            if ($source->getPlanetId() === $drop->getPlanetId() || !$this->nearCap($source)) {
  114	                continue;
  115	            }
  116	
  117	            $floor = $this->reserveFloor->floor($source, ReserveFloor::ECONOMY_HOURS);
  118	            $shipment = $this->aboveFloor($source, $floor, $source->getPlanetType() === PlanetType::Moon);
  119	            if (!$this->worthShipping($shipment) || !$this->hasCargo($source, $player)) {
  120	                continue;
  121	            }
  122	
  123	            return app()->makeWith(QueueableTransfer::class, [
  124	                'sourcePlanetId' => $source->getPlanetId(),
  125	                'targetPlanetId' => $drop->getPlanetId(),
  126	                'metal' => (int) round($shipment->metal->get()),
  127	                'crystal' => (int) round($shipment->crystal->get()),
  128	                'deuterium' => (int) round($shipment->deuterium->get()),
  129	            ]);
  130	        }
  131	
  132	        return null;
  133	    }
  134	
  135	    /**
  136	     * The most developed own planet, by the host's building count: the drop the
  137	     * surplus consolidates onto. Moons are never the drop.
  138	     *
  139	     * @param array<PlanetService> $planets
  140	     */
  141	    private function dropBody(array $planets): ?PlanetService
  142	    {
  143	        $best = null;
  144	        foreach ($planets as $planet) {
  145	            if ($planet->getPlanetType() === PlanetType::Moon) {
  146	                continue;
  147	            }
  148	
  149	            if ($best === null || $planet->getBuildingCount() > $best->getBuildingCount()) {
  150	                $best = $planet;
  151	            }
  152	        }
  153	
  154	        return $best;
  155	    }
