  157	    /** Whether either stored resource is at or past the near-cap threshold. */
  158	    private function nearCap(PlanetService $planet): bool
  159	    {
  160	        return $planet->metal()->get() >= self::SURPLUS_RATIO * $planet->metalStorage()->get()
  161	            || $planet->crystal()->get() >= self::SURPLUS_RATIO * $planet->crystalStorage()->get();
  162	    }
  163	
  164	    /** What a body ships above its reserve floor; a moon keeps its deuterium. */
  165	    private function aboveFloor(PlanetService $source, Resources $floor, bool $keepDeuterium): Resources
  166	    {
  167	        return new Resources(
  168	            max(0.0, $source->metal()->get() - $floor->metal->get()),
  169	            max(0.0, $source->crystal()->get() - $floor->crystal->get()),
  170	            $keepDeuterium ? 0.0 : max(0.0, $source->deuterium()->get() - $floor->deuterium->get()),
  171	        );
  172	    }
  173	
  174	    /**
  175	     * What this planet is short for its next level: its price minus what is already there and already
  176	     * flying to it, floored at zero so a planet that has enough ships nothing.
  177	     */
  178	    private function need(PlanetService $target, AiProfile $profile, int $playerId): ?Resources
  179	    {
  180	        $price = $this->nextStepPrice($target, $profile);
  181	        if ($price === null) {
  182	            return null;
  183	        }
  184	
  185	        $inFlight = $this->inFlightTo($target, $playerId);
  186	
  187	        return new Resources(
  188	            max(0.0, $price->metal->get() - $target->metal()->get() - $inFlight->metal->get()),
  189	            max(0.0, $price->crystal->get() - $target->crystal()->get() - $inFlight->crystal->get()),
  190	            max(0.0, $price->deuterium->get() - $target->deuterium()->get() - $inFlight->deuterium->get()),
  191	        );
  192	    }
  193	
  194	    /**
  195	     * The next level this planet wants, in the same order the economy planner takes: storage that is
  196	     * about to overflow, energy before the throttle, the chain's facilities, then the best mine.
  197	     */
  198	    private function nextStepPrice(PlanetService $planet, AiProfile $profile): ?Resources
  199	    {
  200	        $candidates = [
  201	            ...$this->economyUpgrades->storage($planet, $profile),
  202	            ...$this->energyCapacity->pending($planet),
  203	            ...$this->facilityChain->pending($planet),
  204	            ...$this->economyUpgrades->production($planet, $profile),
  205	        ];
  206	
  207	        $first = $candidates[0] ?? null;
  208	        if ($first === null) {
  209	            return null;
  210	        }
  211	
  212	        return ObjectService::getObjectPrice(ObjectService::getObjectById($first->buildingId)->machine_name, $planet);
  213	    }
  214	
  215	    /** The account's own transports already on the way to this body, netted off before the shortfall. */
  216	    private function inFlightTo(PlanetService $target, int $playerId): Resources
  217	    {
  218	        $missions = FleetMission::query()
  219	            ->where('user_id', $playerId)
  220	            ->where('planet_id_to', $target->getPlanetId())
  221	            ->where('mission_type', TransportMission::getTypeId())
  222	            ->where('processed', 0)
  223	            ->where('canceled', 0)
  224	            ->where('time_arrival', '>=', now()->timestamp)
  225	            ->get(['metal', 'crystal', 'deuterium']);
  226	
  227	        return new Resources(
  228	            (float) $missions->sum('metal'),
  229	            (float) $missions->sum('crystal'),
  230	            (float) $missions->sum('deuterium'),
  231	        );
  232	    }
  233	
  234	    /**
  235	     * The first other body that can spare the shipment and still keep its own reserve.
  236	     *
  237	     * @param array<PlanetService> $planets
  238	     */
  239	    private function source(array $planets, PlanetService $target, Resources $need, PlayerService $player): ?PlanetService
  240	    {
  241	        foreach ($planets as $source) {
  242	            if ($source->getPlanetId() === $target->getPlanetId()) {
  243	                continue;
  244	            }
  245	
  246	            $floor = $this->reserveFloor->floor($source, ReserveFloor::ECONOMY_HOURS);
  247	            // A resource the shipment does not carry keeps no floor: the source only reserves what it
  248	            // actually spends, so a metal-and-crystal ferry is not blocked by a deuterium reserve.
  249	            // ponytail: deuterium fuel is not reserved here (it is distance- and fleet-dependent), so
