266	    /**
267	     * A ferry needs a hull with a hold: a source with no cargo ships can never fly, so the planner
268	     * does not publish that transfer. `ponytail:` asks "any cargo", not "enough" — an under-supplied
269	     * source still refuses at dispatch (`NoTransportFleet`), bounded by the account building cargo;
270	     * the upgrade is comparing `getTotalCargoCapacity` to the shipment here.
271	     */
272	    private function hasCargo(PlanetService $source, PlayerService $player): bool
273	    {
274	        return $source->getShipUnits()->getTotalCargoCapacity($player) > 0;
275	    }
