  196	    private function rankedProduction(PlanetService $planet, AiProfile $profile, float $horizon): array
  197	    {
  198	        $entries = [];
  199	
  200	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
  201	            if (!BuildingQueueObject::accepts($object->machine_name)) {
  202	                continue;
  203	            }
  204	
  205	            $gain = $this->productionGainOfNextLevel($planet, $object->machine_name);
  206	            if ($gain <= 0.0) {
  207	                continue;
  208	            }
  209	
  210	            $entries[] = [
  211	                'hours' => $this->paybackHours($profile, (int) $object->id, ObjectService::getObjectPrice($object->machine_name, $planet), $gain),
  212	                'buildTime' => $planet->getBuildingConstructionTime($object->machine_name),
  213	                'candidate' => app()->makeWith(BuildCandidate::class, [
  214	                    'buildingId' => $object->id,
  215	                    'reason' => 'economy:' . $object->machine_name,
  216	                ]),
  217	            ];
